-- A person's plans: an amount the claim form would take, a start date, every N days (at least 1) and
-- an end date (not before the start). Generating makes a DRAFT claim for each plan date (the start,
-- then every N days) up to the end and the sheet's today that has none yet; plan_claim records each
-- date a plan has made its claim for, so a date is made once, and a date refused is tried again.
CREATE TABLE plan (
    id BIGINT AUTO_INCREMENT PRIMARY KEY,
    sheet_id VARCHAR(200) NOT NULL REFERENCES sheet(id),
    person_id BIGINT NOT NULL REFERENCES person(id),
    amount DECIMAL(19, 2) NOT NULL,
    start_date DATE NOT NULL,
    every_days INT NOT NULL,
    end_date DATE NOT NULL
);
CREATE TABLE plan_claim (
    plan_id BIGINT NOT NULL REFERENCES plan(id),
    claim_date DATE NOT NULL,
    claim_id BIGINT NOT NULL,
    PRIMARY KEY (plan_id, claim_date)
);
-- A plan may instead run monthly on a day of the month (1 to 31): that day in every month from the
-- start's month (a day beyond the month's length falls on its last day), dates before the start left
-- out. A plan has either every_days or day_of_month, never both.
ALTER TABLE plan ALTER COLUMN every_days SET NULL;
ALTER TABLE plan ADD COLUMN day_of_month INT;
-- A plan's pauses: paused on the sheet's today, resumed on the sheet's today (null: still paused). A
-- plan date on or after the day it was paused and before the day it was resumed is skipped, not
-- postponed: generate makes nothing for it and the plan's next dates leave it out.
CREATE TABLE plan_pause (
    id BIGINT AUTO_INCREMENT PRIMARY KEY,
    plan_id BIGINT NOT NULL REFERENCES plan(id),
    paused_on DATE NOT NULL,
    resumed_on DATE
);
