313	/**
314	 * A person's plan on a sheet: an amount with two decimals, made a DRAFT claim on its start date, then
315	 * every {@code every} days or monthly on day {@code day} of the month (the other null), up to its end date. {@code generated} is how many claims it has made so far.
316	 * {@code pauses} are its pauses, in order: a plan date in one is skipped, not postponed.
317	 */
318	public record Plan(Long id, String sheetId, long personId, BigDecimal amount, LocalDate start, Integer every,
319	        Integer day, LocalDate end, int generated, List<PlanPause> pauses) {
320	
321	    /** Whether the plan is paused now: its last pause not yet resumed. */
322	    public boolean paused() {
323	        return !pauses.isEmpty() && pauses.get(pauses.size() - 1).resumedOn() == null;
324	    }
325	
326	    private boolean skipped(LocalDate date) {
327	        return pauses.stream().anyMatch(p -> p.skips(date));
328	    }
329	
330	    /**
331	     * The plan dates up to {@code last}, in order: its start then every N days; or, monthly, that day in
332	     * every month from the start's month (a day beyond the month's length falling on its last day),
333	     * dates before the start left out, and dates in a pause skipped.
334	     */
335	    public List<LocalDate> datesUpTo(LocalDate last) {
336	        List<LocalDate> dates = new ArrayList<>();
337	        if (day != null) {
338	            for (LocalDate month = start.withDayOfMonth(1); !month.isAfter(last); month = month.plusMonths(1)) {
339	                LocalDate date = month.withDayOfMonth(Math.min(day, month.lengthOfMonth()));
340	                if (!date.isBefore(start) && !date.isAfter(last) && !skipped(date)) dates.add(date);
341	            }
342	        } else {
343	            for (LocalDate date = start; !date.isAfter(last); date = date.plusDays(every)) {
344	                if (!skipped(date)) dates.add(date);
345	            }
346	        }
347	        return dates;
348	    }
349	
350	    /** The first {@code count} plan dates after {@code today} and on or before its end, in order. */
351	    public List<LocalDate> nextDates(LocalDate today, int count) {
352	        return datesUpTo(end).stream().filter(d -> d.isAfter(today)).limit(count).toList();
353	    }
354	}
