613	    public void validate(@RequestBody PlanRequest request, Out<PlanInput> body) throws InvalidPlanException {
614	        if (request == null) throw new InvalidPlanException("A plan needs an amount, a start, every N days and an end");
615	        ClaimInput claim;
616	        try {
617	            claim = ClaimInput.from(new ClaimRequest(request.amount(), "", "", "", "", ""));
618	        } catch (InvalidClaimException e) {
619	            throw new InvalidPlanException(e.getMessage());
620	        }
621	        LocalDate start = date(request.start(), "A start date");
622	        LocalDate end = date(request.end(), "An end date");
623	        if (end == null) throw new InvalidPlanException("An end date is required");
624	        String rawEvery = request.every() == null ? "" : request.every().trim();
625	        String rawDay = request.day() == null ? "" : request.day().trim();
626	        Integer every = null;
627	        Integer day = null;
628	        if (!rawDay.isEmpty()) {
629	            if (!rawEvery.isEmpty()) throw new InvalidPlanException("A plan runs every N days or on a day of the month, not both");
630	            if (!rawDay.matches("\\d{1,2}") || Integer.parseInt(rawDay) < 1 || Integer.parseInt(rawDay) > 31) {
631	                throw new InvalidPlanException("The day of the month is a whole number from 1 to 31");
632	            }
633	            day = Integer.parseInt(rawDay);
